using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Services;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

public class Course
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = "";
    public string InstructorName { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Student name is required.")]
    public string? StudentName { get; set; }

    [Required(ErrorMessage = "Student ID is required.")]
    public string? StudentId { get; set; }

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Explore the theory and practice of computing, from algorithms and data structures to artificial intelligence and software engineering." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study the language of the universe through pure and applied mathematics, statistics, and mathematical modeling." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Develop critical thinking and communication skills through the study of literature, rhetoric, and creative writing." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of experience teaching introductory programming. Her research focuses on CS education and making computing accessible to all students.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures and Algorithms", Description = "Study fundamental data structures including arrays, linked lists, trees, hash tables, and graphs. Analyze algorithm efficiency using Big-O notation and implement classic sorting and searching algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. James Rivera", InstructorBio = "Dr. Rivera is an associate professor specializing in algorithm design and optimization. He has published extensively in top-tier conferences and previously worked as a software engineer at Google.", IsFeatured = false },
            new() { Id = 3, Title = "Database Systems", Description = "Covers relational database design, SQL, normalization, transaction management, and an introduction to NoSQL databases. Students complete a semester-long project building a full database application.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez spent a decade in industry at Oracle and Microsoft before joining academia. She specializes in distributed databases and data engineering.", IsFeatured = false },
            new() { Id = 4, Title = "Artificial Intelligence", Description = "An introduction to the principles and techniques of artificial intelligence including search, knowledge representation, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of experience teaching introductory programming. Her research focuses on CS education and making computing accessible to all students.", IsFeatured = true },

            // Mathematics
            new() { Id = 5, Title = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications include rates of change, optimization, and area under curves. A foundational course for STEM majors.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a professor of mathematics with over 20 years of teaching experience. He is known for his engaging lectures and has received multiple teaching awards. His research is in differential equations.", IsFeatured = true },
            new() { Id = 6, Title = "Linear Algebra", Description = "Study vector spaces, matrices, determinants, eigenvalues, and linear transformations. Applications to computer graphics, data science, and engineering are explored throughout the course.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Emily Nakamura", InstructorBio = "Dr. Nakamura's research bridges pure mathematics and machine learning. She completed her postdoc at Stanford and is passionate about showing students the beauty and utility of abstract algebra.", IsFeatured = false },
            new() { Id = 7, Title = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, confidence intervals, and regression analysis. Emphasizes real-world applications and data interpretation.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is a professor of mathematics with over 20 years of teaching experience. He is known for his engaging lectures and has received multiple teaching awards. His research is in differential equations.", IsFeatured = false },
            new() { Id = 8, Title = "Discrete Mathematics", Description = "Logic, set theory, combinatorics, graph theory, and mathematical proofs. Essential for computer science students and anyone interested in the mathematical foundations of computing.", Credits = 3, Schedule = "Tue/Thu 2:30–3:45 PM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Emily Nakamura", InstructorBio = "Dr. Nakamura's research bridges pure mathematics and machine learning. She completed her postdoc at Stanford and is passionate about showing students the beauty and utility of abstract algebra.", IsFeatured = false },

            // English
            new() { Id = 9, Title = "College Writing", Description = "Develop essential academic writing skills including argumentation, research methods, source evaluation, and revision strategies. Students produce a portfolio of polished essays across multiple genres.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Prof. Angela Torres", InstructorBio = "Prof. Torres is an award-winning writer and educator. Her essays have appeared in The New Yorker and The Atlantic, and she brings real-world publishing experience to the classroom.", IsFeatured = false },
            new() { Id = 10, Title = "American Literature", Description = "A survey of American literature from the colonial period to the present, examining works by Hawthorne, Whitman, Dickinson, Fitzgerald, Morrison, and contemporary authors in their cultural contexts.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Dr. William Okafor", InstructorBio = "Dr. Okafor is a scholar of 20th-century American fiction with a focus on the Harlem Renaissance. He has authored two books on African American literary traditions and mentors aspiring writers.", IsFeatured = true },
            new() { Id = 11, Title = "Creative Writing Workshop", Description = "A workshop-based course in fiction and poetry. Students write original pieces, participate in peer critique sessions, and study the craft through readings by established contemporary authors.", Credits = 3, Schedule = "Wed 3:00–5:30 PM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Prof. Angela Torres", InstructorBio = "Prof. Torres is an award-winning writer and educator. Her essays have appeared in The New Yorker and The Atlantic, and she brings real-world publishing experience to the classroom.", IsFeatured = false },
            new() { Id = 12, Title = "Shakespeare", Description = "An in-depth study of Shakespeare's major plays and sonnets, covering comedies, tragedies, and histories. Explores performance, language, and the enduring relevance of his works.", Credits = 3, Schedule = "Mon/Wed 4:00–5:15 PM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Dr. William Okafor", InstructorBio = "Dr. Okafor is a scholar of 20th-century American fiction with a focus on the Harlem Renaissance. He has authored two books on African American literary traditions and mentors aspiring writers.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

