@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-5">
        <input type="text" name="search" class="form-control" placeholder="Search by name or description…" value="@Search" />
    </div>
    <div class="col-md-4">
        <select name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogService.GetDepartments())
            {
                <option value="@dept.Code" selected="@(Department == dept.Code)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = CatalogService.GetCourses(Search, Department);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <table class="table table-striped table-hover">
        <thead class="table-dark">
            <tr>
                <th>Course</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Title</td>
                    <td>@course.DepartmentName</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery(Name = "search")]
    public string? Search { get; set; }

    [SupplyParameterFromQuery(Name = "department")]
    public string? Department { get; set; }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Request Submitted!</h4>
        <p>Thank you, <strong>@Model?.StudentName</strong>. Your enrollment request for
            <strong>@(CatalogService.GetCourse(Model?.CourseId ?? 0)?.Title ?? "the selected course")</strong>
            has been received.</p>
        <p>Your Student ID: <strong>@Model?.StudentId</strong></p>
        <hr />
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="card shadow-sm">
        <div class="card-body">
            <EditForm FormName="enrollment" Method="post" Model="Model" OnValidSubmit="HandleSubmit">
                <AntiforgeryToken />
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Student Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="Model!.StudentName" />
                    <ValidationMessage For="() => Model!.StudentName" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="Model!.StudentId" />
                    <ValidationMessage For="() => Model!.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="Model!.CourseId">
                        <option value="0">-- Select a course --</option>
                        @foreach (var course in CatalogService.GetCourses(null, null))
                        {
                            <option value="@course.Id">@course.Title (@course.DepartmentName)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model!.CourseId" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "courseId")]
    public int? CourseIdFromQuery { get; set; }

    [SupplyParameterFromForm]
    public EnrollmentRequest? Model { get; set; }

    private bool _submitted;

    protected override void OnInitialized()
    {
        Model ??= new EnrollmentRequest();

        if (CourseIdFromQuery.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseIdFromQuery.Value;
        }
    }

    private void HandleSubmit()
    {
        if (Model is not null)
        {
            CatalogService.SubmitEnrollmentRequest(Model);
            _submitted = true;
        }
    }
}

@page "/courses"
